UPDATE articulos a SET contenido=(SELECT string_agg(coalesce(v.texto,substring(a.contenido from v.inicio for v.largo)),'' ORDER BY v.orden) FROM (VALUES (0, 1, 50, NULL::text),(1,0,0,E'<thead><tr><th scope="col">Condición de aceptación del sistema o componente mecánico</th><th scope="col">Cumple</th><th scope="col">No cumple</th><th scope="col">N/A*</th></tr></thead>'),(2, 51, 7, NULL::text),(3, 179, 29, NULL::text),(4,0,0,E'<td colspan="3">'),(5, 212, 146, NULL::text),(6,0,0,E'b) Los forros de balata remachados o atornillados deben tener un grosor igual o mayor a 8 mm (5/16") en remolques o en los ejes traseros de unidades motrices o camiones y a 4.8 mm (3/16") en ejes delanteros al medirse en cualquier punto, excepto la superficie biselada de la zapata o según las especificaciones del fabricante.'),(7, 694, 1577, NULL::text),(8,0,0,E'j) La combinación de desgaste y rectificación en el diámetro interior del tambor debe ser igual o menor que la medida estampada en el tambor; en caso de que la medida no esté estampada en el tambor o, si el límite de desgaste del fabricante del vehículo no está disponible, la combinación de desgaste y rectificación no puede exceder 2.3 mm (0.090") por encima del diámetro original del tambor de 350 mm (14") o menos, o 3.0 mm (0.120") por encima del diámetro original del tambor de más de 350 mm (14").'),(9, 2795, 310, NULL::text)) v(orden,inicio,largo,texto)) WHERE a.id='f10dd9fb-e1ab-5010-aa54-a38b35466b86' AND md5(a.contenido)='3c45ccc4d51952b0b4b950d871ef64ed' RETURNING a.id,md5(a.contenido) hash;